    "notes": [
      "The Geneva Office under the Information Section is essentially the whole section. In the Liste du Personnel it is written this way to distinguish between foreign offices and the office most closely connected to the Secretariat. The director is placed under the Geneva Office.",
      "In 1931 the Economic and Financial Section was divided into two separate sections because of the volume of administrative financial work.",
      "The Epidemiological Intelligence Service / Rockefeller Grant appears to become its own section in 1931, although some attachment between the units can still be assumed."
    ]
